SELECT COUNT(*) FROM grade g JOIN enrollment e ON g.enrollment_id = e.id JOIN course c ON e.course_id = c.id LEFT JOIN student s ON e.student_id = s.id LEFT JOIN subject sj ON c.subject_id = sj.id WHERE c.professor_id = #{professorId} AND c.id = #{courseId} AND sj.id = #{subjectId}
AND (
s.name LIKE '%' || #{searchKeyword} || '%' s.student_no LIKE '%' || #{searchKeyword} || '%' sj.name LIKE '%' || #{searchKeyword} || '%'
)

SELECT *
FROM (
SELECT t.*, ROWNUM rn
FROM (
SELECT
g.id, g.alphabet, g.gpa AS GPA, g.score, g.total_int,
g.mid_exam, g.final_exam, g.assignment, g.attendance,
g.student_id, g.enrollment_id, sj.name AS subjectName
FROM grade g
JOIN enrollment e ON g.enrollment_id = e.id
JOIN course c ON e.course_id = c.id
LEFT JOIN student s ON e.student_id = s.id
LEFT JOIN subject sj ON c.subject_id = sj.id
WHERE c.professor_id = #{professorId}
AND c.id = #{courseId}
AND sj.id = #{subjectId}

    AND (


            s.name LIKE '%' || #{searchKeyword} || '%'
            s.student_no LIKE '%' || #{searchKeyword} || '%'
            sj.name LIKE '%' || #{searchKeyword} || '%'


    )

ORDER BY g.id DESC
) t
WHERE ROWNUM <= #{end}
)
WHERE rn > #{start}

