mapper.select:
SELECT * FROM ( SELECT t.*, ROWNUM rn FROM ( SELECT g.id, g.alphabet, g.gpa AS GPA, g.score, g.total_int, g.mid_exam, g.final_exam, g.assignment, g.attendance, g.student_id, g.enrollment_id, sj.name AS subjectName FROM grade g JOIN enrollment e ON g.enrollment_id = e.id JOIN course c ON e.course_id = c.id LEFT JOIN subject sj ON c.subject_id = sj.id WHERE g.student_id = #{studentId}
AND ( TO_CHAR(g.id) LIKE '%' || #{searchKeyword} || '%' OR UPPER(sj.name) LIKE '%' || UPPER(#{searchKeyword}) || '%' OR UPPER(g.alphabet) LIKE '%' || UPPER(#{searchKeyword}) || '%' )
AND g.id = TO_NUMBER(#{searchKeyword})
AND UPPER(sj.name) LIKE '%' || UPPER(#{searchKeyword}) || '%'
AND UPPER(g.alphabet) LIKE '%' || UPPER(#{searchKeyword}) || '%'
ORDER BY g.id DESC ) t WHERE ROWNUM <= #{end} ) WHERE rn > #{start}

SELECT id, subject_id AS subjectId, enrollment_id AS enrollmentId, alphabet, boundary FROM alphabet_system
subject_id = #{subjectId}
AND enrollment_id = #{enrollmentId}
ORDER BY boundary DESC

SELECT course_id
FROM enrollment
WHERE id = #{enrollmentId}

SELECT COUNT(*)
FROM grade g
         JOIN enrollment e ON g.enrollment_id = e.id
         JOIN course c     ON e.course_id     = c.id
WHERE g.id = #{gradeId}
  AND c.professor_id = #{professorId}
